// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FinanceCommissionRule) predicate.FinanceCommissionRule {
	return predicate.FinanceCommissionRule(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FinanceCommissionRule) predicate.FinanceCommissionRule {
	return predicate.FinanceCommissionRule(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FinanceCommissionRule) predicate.FinanceCommissionRule {
	return predicate.FinanceCommissionRule(sql.NotPredicates(p))
}
